div.style:
font-family: 'DejaVu Sans', Arial, sans-serif;
font-size: 9.5px;
color: #111;
direction: rtl;
unicode-bidi: embed;
padding: 0;
margin: 0;

td.style:
border:1px solid #ddd;
padding:6px;
direction:rtl;
unicode-bidi:embed;
white-space:normal;
word-break:break-word;
overflow-wrap:break-word;
font-size:11px;
color:#222;
line-height:1.5;
